/**
 * CI-ONLY test double for the statutorily scoped payment-proof HTTP acceptance.
 * This is NOT an antivirus engine, is never used in production, and only
 * accepts a byte marker generated by a disposable-PostgreSQL test fixture.
 * Normal malware scanner configuration and fail-closed production code remain
 * unchanged. Any nonfixture byte stream is REJECTED, never marked scanned.
 */
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createServer } from "node:https";
import { timingSafeEqual } from "node:crypto";

assert.equal(process.env.CI, "true");
assert.equal(process.env.GITHUB_ACTIONS, "true");
assert.equal(process.env.TENANT_SYNTHETIC_SCAN_MODE, "isolated-pg16-only");
assert.equal(process.env.DEMO_MODE, "false");
const db = new URL(process.env.DATABASE_URL ?? "");
assert.equal(db.hostname, "127.0.0.1");
assert.equal(db.port, "5432");
assert.equal(db.pathname, "/app_db");
const certificate = readFileSync("/tmp/tenant-ci-scanner.crt");
const key = readFileSync("/tmp/tenant-ci-scanner.key");
const acceptedToken = Buffer.from("ci-tenant-proof-scanner-only");
const json = (res, code, body) => {
  res.writeHead(code, { "content-type": "application/json", "cache-control": "no-store" });
  res.end(JSON.stringify(body));
};
const server = createServer({ cert: certificate, key }, async (req, res) => {
  if (req.method === "GET" && req.url === "/health") {
    json(res, 200, { ready: true, simulated: true }); return;
  }
  if (req.method !== "POST" || req.url !== "/scan") {
    json(res, 404, { error: "Not found" }); return;
  }
  const receivedToken = Buffer.from((req.headers.authorization ?? "").replace(/^Bearer /i, ""));
  if (acceptedToken.length !== receivedToken.length ||
      !timingSafeEqual(acceptedToken, receivedToken)) {
    json(res, 401, { error: "CI fixture scanner unauthorized" }); return;
  }
  const chunks = [];
  let count = 0;
  for await (const chunk of req) {
    count += chunk.length;
    if (count > 8192) {
      json(res, 413, { error: "Only small synthetic fixture files allowed" }); return;
    }
    chunks.push(chunk);
  }
  const body = Buffer.concat(chunks).toString("utf8");
  const allowed = body.startsWith("%PDF-1.4\nSYNTHETIC-PROOF-TENANT-QA:") &&
    body.endsWith("\n%%EOF\n") && body.length < 1024;
  json(res, 200, allowed
    ? { clean: true, engine: "CI simulated source isolation fixture (NOT antivirus)" }
    : { clean: false, engine: "CI fixture rejection", threat: "Non-synthetic input" });
});
server.listen(8443, "127.0.0.1", () => {
  console.log("CI-only synthetic proof scanner listening on 127.0.0.1:8443");
});
